// Intents: What a post can be.
type Intents struct {
	rows []Intent
}

// Len returns the number of entries.
func (self *Intents) Len() int { return len(self.rows) }

// At returns entry i, in source order.
func (self *Intents) At(i int) *Intent { return &self.rows[i] }

// All yields every entry in source order.
func (self *Intents) All() iter.Seq[*Intent] {
	return func(yield func(*Intent) bool) {
		for i := range self.rows {
			if !yield(&self.rows[i]) {
				return
			}
		}
	}
}

// Find returns the entry whose id is key.
func (self *Intents) Find(key string) (*Intent, bool) {
	id, ok := ParseIntentID(key)
	if !ok {
		return nil, false
	}
	return &self.rows[id.Position()], true
}

func (self *Intents) Get(id IntentID) *Intent { return &self.rows[id.Position()] }

